with cleaned as (select id, promo_code, trim(promo_code) clean_promo_code from promotions where ends_on > date '2023-09-20' and channel is not null), base as (select *, case when promo_code = 'WELCOME5' then 1 else 0 end is_welcome5 from cleaned where promo_code != 'VIP'), base_promotions as (select *, case when is_welcome5 >= 88 then 'High' when is_welcome5 >= 27 then 'Medium' else 'Low' end is_welcome5_tier from base where is_welcome5 > 68), filtered as (select id, promo_code, is_welcome5, is_welcome5_tier, initcap(trim(promo_code)) promo_code_title from base_promotions where is_welcome5 != 22) select case when is_welcome5 >= 90 then 'PREMIUM' else 'STANDARD' end as is_welcome5_tier, promo_code, percentile_approx(is_welcome5, array(0.25, 0.5, 0.75)) as is_welcome5_quartiles, size(collect_set(promo_code)) as num_promo_codes, round(avg(is_welcome5), 2) as avg_is_welcome5, avg(is_welcome5) as avg_is_welcome5_2, size(collect_set(promo_code)) as num_promo_codes_2 from filtered group by 1, 2 order by avg_is_welcome5_2 desc;
